                    "sql": "Create or replace table MapleMonk.zouk_MARKETING_CONSOLIDATED_DTC as select * from MapleMonk.zouk_MARKETING_CONSOLIDATED where lower(Channel) like any (\'%facebook%\',\'%google%\',\'%contlo%\',\'%bitespeed%\') ; Create or replace table MapleMonk.zouk_MARKETING_CONSOLIDATED_MP as select * from MapleMonk.zouk_MARKETING_CONSOLIDATED where not(lower(Channel) like any (\'%facebook%\',\'%google%\',\'%contlo%\',\'%bitespeed%\')) ; Create or replace table Maplemonk.zouk_new_initiative_MP AS select * from `MapleMonk.zouk_MARKETING_CONSOLIDATED` where CAMPAIGN_ID like \'120229486049350758\' ; Create or replace table maplemonk.zouk_sales_consolidated_DTC as select * from maplemonk.zouk_sales_consolidated where not(lower(MARKETPLACE_SEGMENT) like any (\'%commerce%\',\'%offline%\')) ; Create or replace table `MapleMonk.Zouk_Product_Sales_Cost_Source_DTC` as select * from MapleMonk.Zouk_Product_Sales_Cost_Source where (lower(MARKETPLACE) like any (\'shopify\',\'shopify web\',\'shopify app\', \'shopify ios app\',\'shopify android app\')) ; Create or replace table `MapleMonk.Zouk_Product_Seconday_Sales_Cost_Source_MP` as select * from MapleMonk.Zouk_Product_Secondary_Sales_Cost_Source where (lower(MARKETPLACE_SEGMENT) like any (\'%commerce%\')) ; Create or replace table maplemonk.zouk_sales_consolidated_DTC as select * from maplemonk.zouk_sales_consolidated where not(lower(MARKETPLACE_SEGMENT) like any (\'%commerce%\',\'%offline%\')) ; Create or replace table maplemonk.zouk_sales_cost_source_DTC as select * from maplemonk.zouk_sales_cost_source where lower(Marketplace) like any (\'%shopify%\',\'%website%\',\'app\') ; Create or replace table maplemonk.zouk_sales_cost_source_MP as select * from maplemonk.zouk_sales_cost_source where not(lower(Marketplace) like any (\'%shopify%\',\'%website%\',\'app\',\'%offline%\',\'%ebo%\')) ; Create or replace table maplemonk.zouk_sales_consolidated_MP as select * from maplemonk.zouk_sales_consolidated where lower(MARKETPLACE_SEGMENT) like \'%commerce%\' ; create or replace table `MapleMonk.zouk_Mens_collection_Secondary_Sales` as select * from `MapleMonk.zouk_Secondary_sales_consolidated` where lower(COLLECTION) like \'%men%\' ; Create or replace table maplemonk.zouk_sales_consolidated_offline as select s.*, m.City as Store_City, m.Tier, m.State as Store_State, m.Region, m.Store_Type, m.City_Cluster, m.Store_Classification, SUM(IFNULL(selling_price,0)) OVER (PARTITION BY reference_code) AS order_total_value, COUNT(1) OVER (PARTITION BY reference_code) AS order_line_count, (CASE WHEN SUM(IFNULL(selling_price,0)) OVER (PARTITION BY reference_code) >= 10000 THEN 30 WHEN SUM(IFNULL(selling_price,0)) OVER (PARTITION BY reference_code) >= 5000 THEN 12 ELSE 0 END) / NULLIF(COUNT(1) OVER (PARTITION BY reference_code), 0) AS runs_per_row from maplemonk.zouk_sales_consolidated s left join `MapleMonk.Zouk_EBO_Store_Master` m on UPPER(s.Store_Code) = UPPER(m.Store_Code) AND lower(s.source) = lower(m.Store_Name) where (lower(MARKETPLACE_SEGMENT) like any (\'%offline%\',\'%ebo%\')) ; Create or replace table Maplemonk.zouk_BBF_Activity_Table AS select Order_Date, sum(ifnull(QUANTITY,0)) as Units_Sold, count(distinct ORDER_ID) as Total_Orders from `MapleMonk.zouk_sales_consolidated` where ORDER_STATUS not like \'%cancel%\' group by 1 ; Create or replace table maplemonk.zouk_secondary_sales_consolidated_MP as select * from maplemonk.zouk_secondary_sales_consolidated where lower(MARKETPLACE_SEGMENT) like \'%commerce%\' ; Create or replace table maplemonk.zouk_pandl_offline as select * from maplemonk.zouk_pandl where lower(final_Marketplace) like any (\'%offline%\',\'ebo\') ; Create or replace table maplemonk.zouk_pandl_DTC as select * from maplemonk.zouk_pandl where (lower(final_Marketplace) like any (\'%shopify%\',\'%website%\',\'app\')) ; Create or replace table maplemonk.zouk_pandl_MP as select * from maplemonk.zouk_pandl where not(lower(final_Marketplace) like any (\'%shopify%\',\'%website%\',\'app\',\'%offline%\',\'ebo\')) ; CREATE OR REPLACE TABLE MapleMonk.Zouk_Power_Potli_Data AS select * from `MapleMonk.zouk_Secondary_sales_consolidated` where lower(PRODUCT_CATEGORY) like \'%power%\' ; CREATE OR REPLACE TABLE MapleMonk.zouk_Luggage_Secondary_PandL AS SELECT * FROM `MapleMonk.zouk_secondary_pandl` WHERE LOWER(COLLECTION) like \'%luggage%\' ; CREATE OR REPLACE TABLE MapleMonk.Zouk_Lineitem_Pricing_Report AS SELECT NAME, Date(safe_cast(created_at as datetime)) As Created_At, JSON_EXTRACT_SCALAR(line_item_json, \'$.title\') AS LineItem_Name, JSON_EXTRACT_SCALAR(line_item_json, \'$.sku\') AS LineItem_SKU, CAST(JSON_EXTRACT_SCALAR(line_item_json, \'$.price\') AS FLOAT64) AS LineItem_Price, CAST(JSON_EXTRACT_SCALAR(line_item_json, \'$.quantity\') AS INT64) AS LineItem_Quantity FROM `zouk-wh.maplemonk.Shopify_zoukbags_ORDERS`, UNNEST(line_items) AS line_item_json ; CREATE OR REPLACE TABLE MapleMonk.zouk_Store_AOV_Achievement AS WITH weekly_aov AS ( SELECT Store_Code, source, DATE_TRUNC(order_date, WEEK(MONDAY)) AS week_start, SUM(selling_price) / COUNT(DISTINCT order_id) AS AOV FROM `maplemonk.zouk_sales_consolidated_offline` WHERE order_date IS NOT NULL and lower(ORDER_STATUS) not like \'%cancel%\' and lower(FINAL_MARKETPLACE) like \'ebo\' GROUP BY 1,2,3 ) SELECT Store_Code, Source AS Store_Name, week_start, AOV, 2400 AS target_aov, CASE WHEN AOV >= 2400 THEN 24 ELSE 0 END AS runs FROM weekly_aov ;",
                    "transaction": true
                }
            ) }}
